   const rec = m => ({ analysis: { metrics: { taskMs: { key: 'taskMs', primary: true, ...m } } } });
   assert.equal(screeningVerdict(rec({ outcome: 'worse', lo: 3, hi: 5 }), 2).exceeds, true);
